        "openAccessInfo": {
          "license": "CCBYNCND",
          "status": "GOLD",
          "disclaimer": "Notice: This snippet is extracted from the open access paper or abstract available at https://api.unpaywall.org/v2/10.3998/MJCSLOA.3239521.0023.202?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.3998/MJCSLOA.3239521.0023.202, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
        }
